#include <bits/stdc++.h>
using namespace std;

void solve() {
    int pages;
    cin >> pages;

    int arr[7];
    int sum = 0;

    for (int i = 0; i < 7; ++i) {
        cin >> arr[i];
        sum += arr[i];
    }

    pages %= sum;
    if (pages == 0) pages = sum;

    for (int i = 0; i < 7; ++i) {
        if (pages <= arr[i]) {
            cout << i + 1 << '\n';
            return;
        }
        pages -= arr[i];
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    solve();
    return 0;
}

